INSERT INTO logic_rules VALUES(4,'LR-CALC-RATE-MULTIPLY','subtotal equals quantity multiplied by configured rate','2026-04-18 11:37:58');
INSERT INTO logic_rules VALUES(5,'LR-CALC-SUM','page subtotal equals sum of rule outputs','2026-04-18 11:37:58');
