INSERT INTO line_items VALUES(3361,'ab13a','additional_building_work_page','Additional Building Works','Conceal Flank & Rear Wall Steels','N',0.0,0.0,'admin_only',NULL,'Flank and rear wall steels are to be concealed within the ceiling as best as possible. This allows for the creation of 2 holes within the steel beam accommodating 1st floor bathroom pipes. This is subject to an onsite inspection',NULL,'ab13#','auto_child',NULL,NULL,0,220,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3362,'ab13b*','additional_building_work_page','Additional Building Works','Conceal Flank & Rear Wall Steels (guidance)','N',0.0,0.0,'admin_only',NULL,NULL,'£3,500 | *PLEASE NOTE –  1ST FLOOR DISTURBANCE – THIS IS LIKELY TO CAUSE SOME LOW-LEVEL DAMAGE TO THE 1ST FLOOR BEDROOM & BATHROOM ABOVE. THE COST TO REPAIR AND MAKE GOOD IS TO BE ASSESSED/ PRICED ON SITE BY OUR FINISHINGS TEAM. REDUCTION TO EXISTING CEILING – IN ORDER TO ACHIEVE A COMPLETELY FLUSH FINISH IT MAY ALSO BE NECESSARY TO SLIGHTLY REDUCE THE EXISTING CEILING HEIGHT AND CREATE A NEW SUSPENDED CEILING. THE ADDITIONAL COST SHOULD THIS BE REQUIRED IS P/C £700* CHIMNEY STEELS – SHOULD THE CLIENT WISH TO REMOVE THE CHIMNEY THEN THE COST TO CONCEAL THE CHIMNEY STEELS WILL BE AN ADDITIONAL £1,155.',NULL,'guidance',NULL,NULL,0,221,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3363,'ab14#','additional_building_work_page','Additional Building Works','Conceal Flank, Rear Wall & Chimney Steels','N',3000.0,1.0,'admin_only','CONCEAL FLANK, REAR WALL & CHIMNEY STEELS',NULL,NULL,NULL,'parent',NULL,NULL,1,222,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3364,'ab14a','additional_building_work_page','Additional Building Works','Conceal Flank, Rear Wall & Chimney Steels (notes)','N',0.0,0.0,'admin_only',NULL,'Flank, rear wall and chimney steels are to be concealed within the ceiling as best as possible. This allows for creation of 2 holes in the steel beam to accommodate 1st floor bathroom pipes. Subject to an onsite inspection.',NULL,'ab14#','auto_child',NULL,NULL,0,223,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3365,'ab14b*','additional_building_work_page','Additional Building Works','Conceal Flank, Rear Wall & Chimney Steels (guidance)','N',0.0,0.0,'admin_only',NULL,NULL,'£4,700 | *PLEASE NOTE – !ST FLOOR DISTURBANCE – LIKELY TO CAUSE SOME LOW-LEVEL DAMAGE TO THE 1ST FLOOR BEDROOM & BATHROOM ABOVE. COST TO REPAIR & MAKE GOOD TO BE ASSESSED/ PRICED ON SITE BY FINISHINGS TEAM. REDUCTION TO EXISTING CEILING – IN ORDER TO ACHIEVE A COMPLETELY FLUSH FINISH IT MAY ALSO BE NECESSARY TO SLIGHTLY REDUCE THE EXISTING CEILING HEIGHT AND CREATE A NEW SUSPENDED CEILING. THE ADDITIONAL COST SHOULD THIS BE REQUIRED IS P/C £700*',NULL,'guidance',NULL,NULL,0,224,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
