INSERT INTO line_items VALUES(3597,'pl14b','additional_costs_page','Plumbing','Relocate Existing Boiler (guidance)','N',0.0,0.0,'admin_only',NULL,NULL,'*PLEASE NOTE – TO BE FITTED WITHIN 5M OF ORIGINAL LOCATION. SHOULD THE BOILER BE LOCATED ON A WALL THAT IS BEING REMOVED AND THEREFOR NEEDS TO BE RELOCATED TEMPORARILY UNTIL THE NEW LOCATION IS COMPLETED – ADDITIONAL £650. PLUS ROOMS CANNOT GUARANTEE THAT THE EXISTING BOILER WILL FUNCTION TO THE SAME CAPACITY ONCE MOVED. THE CLIENT CAN ALTERNATIVELY CONSULT WITH THE PLUMBER ABOUT INSTALLING A NEW BOILER. THE REPLACING/ RELOCATING OF A BOILER IS TO BE ASSESSED & PRICED ON-SITE BY THE PLUMBER. THE NEW BOILER SYSTEM WILL WORK IN CONJUNCTION WITH AN UNVENTED HOT WATER CYLINDER. THE CYLINDER IS INCLUDED AS PART OF THE LOFT QUOTATION.',NULL,'auto_child',NULL,NULL,0,456,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
