INSERT INTO line_items VALUES(3848,'co1a','summary_page','Contingency','Using neighbours party wall (notes)','N',0.0,0.0,'admin_only',NULL,'If we are making use of an existing party wall, that has been constructed by your neighbour, the neighbour will be entitled to a contribution to the cost of constructing that wall. This is known as ‘enclosure costs’ and you will be responsible for paying it. The cost will be dependent on the size and construction of the wall you are making use of. The estimated enclosure cost is approx. £…',NULL,NULL,'auto_child',NULL,NULL,0,707,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
