INSERT INTO line_items VALUES(3853,'co4','summary_page','Contingency','PARTY WALL AGREEMENT - SURVEYOR','Y',1400.0,1.0,'admin_only','PARTY WALL AGREEMENT - SURVEYOR',NULL,NULL,NULL,'standalone',NULL,NULL,1,712,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3854,'co4a','summary_page','Contingency','PARTY WALL AGREEMENT - SURVEYOR (notes)','Y',0.0,0.0,'admin_only',NULL,'Your neighbours are entitled to a party wall agreement. If required, you will need to appoint a surveyor to act on your behalf in relation to these matters. In this event you will be responsible for the fees of the surveyor/s. A typical cost for a surveyor to prepare a party wall agreement acting for yourselves AND your neighbours is p/c £1,440 inc. VAT.  Plus Rooms will arrange for party wall notices to be prepared. If your neighbours’ consent to these notices then you will not need to appoint a surveyor',NULL,NULL,'auto_child',NULL,NULL,0,713,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3855,'co5','summary_page','Contingency','Party Wall Notices - First Notice','Y',180.0,1.0,'admin_only','Party Wall Notices',NULL,NULL,NULL,'standalone',NULL,NULL,1,714,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3856,'co5a','summary_page','Contingency','Party Wall Notices - First Notice (notes)','Y',0.0,0.0,'admin_only',NULL,'The cost for the Party Wall Surveyor to provide notices for your project will be £180 for the first notice and £110 for every notice thereafter. This will be paid directly to the company at the same time as the PPP.',NULL,NULL,'auto_child',NULL,NULL,0,715,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
