INSERT INTO line_items VALUES(3862,'co8a','summary_page','Contingency','Party Wall Finish (notes)','Y',0.0,0.0,'admin_only',NULL,'If you agree with your neighbour to construct the new wall as a party wall and the party wall surveyor/s insist on the wall being terminated with a parapet and coping stone there will be an additional cost of £180 per metre.',NULL,NULL,'auto_child',NULL,NULL,0,721,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
