INSERT INTO line_items VALUES(3867,'co11','summary_page','Contingency','Timber hoarding','Y',1500.0,1.0,'admin_only','Timber hoarding',NULL,NULL,NULL,'standalone',NULL,NULL,1,726,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
