INSERT INTO line_items VALUES(3869,'co12','summary_page','Contingency','Replacing the existing floor','Y',385.0,1.0,'admin_only','Replacing the existing floor',NULL,NULL,NULL,'standalone',NULL,NULL,1,728,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3870,'co12a','summary_page','Contingency','Replacing the existing floor (notes)','Y',0.0,0.0,'admin_only',NULL,'If the quote has not specified to replace the existing floor and should the existing floor joists need replacing due to rotting etc the cost to remove the existing joists and lay a concrete insulated floor with damp membrane (compliant with Building Regulations) would be p/c £385 per m2.',NULL,NULL,'auto_child',NULL,NULL,0,729,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3871,'co13','summary_page','Contingency','Existing floor structure','Y',1000.0,1.0,'admin_only','Existing floor structure',NULL,NULL,NULL,'standalone',NULL,NULL,1,730,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3872,'co13a','summary_page','Contingency','Existing floor structure (notes)','Y',0.0,0.0,'admin_only',NULL,'The quote assumes that the original part of the house has wooden joists. Should the existing floors be concrete then additional costs may be incurred due the additional labour required to create pad foundations (for steels) and insert plumbed pipes i.e. wastes etc. p/c £1,000',NULL,NULL,'auto_child',NULL,NULL,0,731,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3873,'co14','summary_page','Contingency','Floor levelling','Y',120.0,1.0,'admin_only','Floor levelling',NULL,NULL,NULL,'standalone',NULL,NULL,1,732,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3874,'co14a','summary_page','Contingency','Floor levelling (notes)','Y',0.0,0.0,'admin_only',NULL,'The new extension floor will be completely level, if additional requirements needed to ensure existing floor is level this can be priced directly by finishing’s team. p/c £120 per m2.',NULL,NULL,'auto_child',NULL,NULL,0,733,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3875,'co14b','summary_page','Contingency','Floor levelling (guidance)','Y',0.0,0.0,'admin_only',NULL,NULL,'*PLEASE NOTE – THIS WILL NOT BE REQUIRED IF THE EXISTING FLOOR IS BEING UPLIFTED AND NEW CONCRETE IS BEING POURED*',NULL,'auto_child',NULL,NULL,0,734,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3876,'co15','summary_page','Contingency','Fast Drying Screed','Y',35.0,1.0,'admin_only','Fast Drying Screed',NULL,NULL,NULL,'standalone',NULL,NULL,1,735,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3877,'co15a','summary_page','Contingency','Fast Drying Screed (notes)','Y',0.0,0.0,'admin_only',NULL,'Tiles can be laid directly onto screed after 48 hours drying time. If however a wooden floor is being laid, 6 weeks drying time will be needed. In order to lay wooden flooring onto screed within 2 weeks of drying time it is possible to upgrade to ‘fast drying screed’ -  additional cost of p/c £650 £35 per m2.',NULL,NULL,'auto_child',NULL,NULL,0,736,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3878,'co15b','summary_page','Contingency','Fast Drying Screed (guidance)','Y',0.0,0.0,'admin_only',NULL,NULL,'*PLEASE NOTE – THIS IS DOWN TO THE VARIATION BEING BETWEEN 3-10CM.',NULL,'auto_child',NULL,NULL,0,737,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3879,'co16','summary_page','Contingency','Ceiling Levelling','Y',100.0,1.0,'admin_only','Ceiling Levelling',NULL,NULL,NULL,'standalone',NULL,NULL,1,738,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3880,'co16a','summary_page','Contingency','Ceiling Levelling (notes)','Y',0.0,0.0,'admin_only',NULL,'This quotation includes fitting new plasterboard directly to the original ceiling joists. Should the original ceiling not be level & the client wish to make it level  - additional cost will be p/c £60 – £100 per m2',NULL,NULL,'auto_child',NULL,NULL,0,739,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3881,'co17','summary_page','Contingency','Roof pitch','Y',50.0,1.0,'admin_only','Roof pitch',NULL,NULL,NULL,'standalone',NULL,NULL,1,740,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3882,'co17a','summary_page','Contingency','Roof pitch (notes)','Y',0.0,0.0,'admin_only',NULL,'Should the architects not be able to achieve the necessary gradient on the roof pitch to accommodate Eternit slates then a specialist slate will be required. p/c £650 £50psm.',NULL,NULL,'auto_child',NULL,NULL,0,741,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
