INSERT INTO line_items VALUES(3886,'co19a','summary_page','Contingency','Thames Water - Build Over agreement lower price (notes)','Y',0.0,0.0,'admin_only',NULL,'Should we be carrying out foundation works within 3 metres of a public sewer, Thames Water’s build over fee will generally be either £343 or £687 depending on the size of the pipe. The Architect will complete relevant forms and oversee application on your behalf at no additional fee.',NULL,NULL,'auto_child',NULL,NULL,0,745,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3887,'co20','summary_page','Contingency','Thames Water - Build Over agreement higher price','N',687.0,1.0,'admin_only','Thames Water - Build Over agreement higher price',NULL,NULL,NULL,'standalone',NULL,NULL,1,746,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3888,'co21','summary_page','Contingency','Deeper Foundation Work - 1m depth','Y',550.0,1.0,'admin_only','Deeper Foundation Work - 1m depth',NULL,NULL,NULL,'standalone',NULL,NULL,1,747,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3889,'co21a','summary_page','Contingency','Deeper Foundation Work - 1m depth (notes)','Y',0.0,0.0,'admin_only',NULL,'Our quote allows for standard 1m deep trench foundation. If deeper foundations are required, for any reason, the additional cost will be p/c £550 per linear metre (per additional 1m depth). Or £585 per linear m where foundations exceed 1.50m in depth. If the foundation depth does exceed 1.50m you will also be required to upgrade the concrete slab to a beam and block floor at an additional cost of £70/m2.',NULL,NULL,'auto_child',NULL,NULL,0,748,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3890,'co21b','summary_page','Uncategorised','Deeper Foundation Work - 1m depth  (guidance)','Y',0.0,0.0,'admin_only',NULL,NULL,'*PLEASE NOTE – IF WE ARE ADDING LOADINGS TO ANY EXISTING WALLS IT MAY BE NECESSARY TO UNDERPIN THESE WALLS AND ADDITIONAL COST WOULD APPLY.',NULL,'auto_child',NULL,NULL,0,749,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
