INSERT INTO line_items VALUES(3904,'co33','summary_page','Contingency','Damp Issues','Y',0.0,0.0,'admin_only','DAMP ISSUES',NULL,NULL,NULL,'standalone',NULL,NULL,1,763,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3905,'co33a','summary_page','Contingency','Damp issues (notes)','Y',0.0,0.0,'admin_only',NULL,'Plus Rooms will not be checking any existing walls for damp penetration. If you have concerns regarding damp, please arrange for a damp specialist to inspect the property prior to works commencing.',NULL,NULL,'auto_child',NULL,NULL,0,764,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
