INSERT INTO line_items VALUES(3907,'co34a','summary_page','Contingency','Existing Walls (notes)','Y',0.0,0.0,'admin_only',NULL,'Unless specified otherwise, If it isn’t possible to skim onto existing walls then the cost to remove and re-plaster board will be assessed on site. £TBA',NULL,NULL,'auto_child',NULL,NULL,0,766,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3908,'co35','summary_page','Contingency','Existing Concrete Floors','Y',0.0,0.0,'admin_only','EXISTING CONCRETE FLOORS',NULL,NULL,NULL,'standalone',NULL,NULL,1,767,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3909,'co35a','summary_page','Contingency','Existing concrete floors (notes)','Y',0.0,0.0,'admin_only',NULL,'If we quote for removing any existing concrete, this is based on the understanding that it is a standard concrete mix i.e. not re-enforced concrete, with a slab no more than 15cm deep. If the concrete mix is non-standard or greater than 15cm the additional cost to remove any necessary sections is to be assessed & priced on site. £TBA',NULL,NULL,'auto_child',NULL,NULL,0,768,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3910,'co36','summary_page','Contingency','Neighbours Ground Level','Y',0.0,0.0,'admin_only','NEIGHBOURS GROUND LEVEL',NULL,NULL,NULL,'standalone',NULL,NULL,1,769,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3911,'co36a','summary_page','Contingency','Neighbours Ground Level (notes)','Y',0.0,0.0,'admin_only',NULL,'Unless explicitly stated within the further requirements section of the Project Details, this quotation has been based on the expectation that the ground level in the adjoining property is similar to yours. Should the neighbours ground level be lower than yours, we will need to increase the depth of the foundations and this will be charged in accordance with the contingency for “Deeper Foundations”. A lower ground level in the adjoining property can also affect the wall height that the council are willing to approve for the extension.',NULL,NULL,'auto_child',NULL,NULL,0,770,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3912,'co37','summary_page','Contingency','Existing Beams','Y',0.0,0.0,'admin_only','EXISTING BEAMS',NULL,NULL,NULL,'standalone',NULL,NULL,1,771,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3913,'co37a','summary_page','Contingency','Existing Beams (notes)','Y',0.0,0.0,'admin_only',NULL,'Any existing beams in the ceiling that are affected by the works will be assessed on site for suitability in terms size and specification. The replacement or amendment of existing beams will be considered an extra and will be priced on site. p/c £TBC',NULL,NULL,'auto_child',NULL,NULL,0,772,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
