INSERT INTO line_items VALUES(3923,'co42a','summary_page','Contingency','Plumbing (notes)','Y',0.0,0.0,'admin_only',NULL,replace('i) Temporary set up – Should the boiler need to be temporarily moved and set up prior to its final relocation or replacement. p/c £650. (*PLEASE NOTE – THIS IS BASED ON MOVING THE BOILER UP TO 1.5M AWAY FROM ITS CURRENT LOCATION.)\nii) On assessment by the plumber you may be advised to have a power flush on existing pipe work. p/c £400.\niii) Upgrading the gas pipe from the gas metre from 22mm to 28mm. p/c £500 – £1,000.\niv) On assessment by the plumber you may be advised to have a pressure test on existing pipework. p/c £200\nv) Replace existing main pipework as a result of upgrading to a pressurised system. p/c £500 – £1,000.\nvi) If the plumber is installing a new combi boiler & converting from a gravity fed system to a pressurised system, depending on existing pipework & location of existing tanks, additional work may be required. p/c £900"','\n',char(10)),NULL,NULL,'auto_child',NULL,NULL,0,782,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3924,'co43','summary_page','Contingency','Undergrouond Pipes','Y',0.0,0.0,'admin_only','UNDERGROUND PIPES',NULL,NULL,NULL,'standalone',NULL,NULL,1,783,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(3925,'co43a','summary_page','Contingency','Undergrouond Pipes  (notes)','Y',0.0,0.0,'admin_only',NULL,replace('i) The quote assumes the drains are of a standard depth approx. 1.00m. We also make the reasonable assumption that we can connect to/extend the existing underground drainage where required.\n*NO ALLOWANCE HAS BEEN MADE TO REPLACE ANY OF THE EXISTING DRAINAGE*.\nii) If pipes are discovered/located under the ground where we are constructing, permission for either relocating the pipes or for bridging over the pipes may be required. The cost and method of proceeding can only be decided after an on-site consultation with the building inspector.\niii)The quotation has allowed for 1x additional inspection chamber. Should Thames Water or building control require any additional manholes there will be an additional cost','\n',char(10)),NULL,NULL,'auto_child',NULL,NULL,0,784,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
