INSERT INTO line_items VALUES(4030,'oe14a','optional_extras_page','Uncategorised','Remove and replace existing kitchen floor (notes)','N',0.0,0.0,'admin_only',NULL,'The additional cost to remove the existing kitchen floor joists and replace with a new fully building regulation compliant concrete insulated floor. This would involve new hardcore, membrane, concrete, insulation and screed. This will create 1 consistent floor composition throughout the entire kitchen.',NULL,'oe14#','auto_child',NULL,NULL,0,889,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
