INSERT INTO line_items VALUES(4033,'oe15a','optional_extras_page','Optional Extras','Conceal/raise flank & rear wall steels (notes)','N',0.0,0.0,'admin_only',NULL,'The flank and rear wall steels are to be concealed within the ceiling as best as possible. This allows for the creation of 2 holes within the steel beam accommodating 1st floor bathroom pipes. This is subject to an onsite inspection.',NULL,NULL,'auto_child',NULL,NULL,0,892,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(4034,'oe15b','optional_extras_page','Optional Extras','Conceal/raise flank & rear wall steels (guidance)','N',0.0,0.0,'admin_only',NULL,NULL,replace(replace('*PLEASE NOTE – \r\n▪ 1ST FLOOR DISTURBANCE – THIS IS LIKELY TO CAUSE SOME LOW-LEVEL DAMAGE TO THE 1ST FLOOR BEDROOM & BATHROOM ABOVE. THE COST TO REPAIR AND MAKE GOOD IS TO BE ASSESSED/ PRICED ON SITE BY OUR FINISHINGS TEAM.\r\n▪ REDUCTION TO EXISTING CEILING – IN ORDER TO ACHIEVE A COMPLETELY FLUSH FINISH IT MAY ALSO BE NECESSARY TO SLIGHTLY REDUCE THE EXISTING CEILING HEIGHT AND CREATE A NEW SUSPENDED CEILING. THE ADDITIONAL COST SHOULD THIS BE REQUIRED IS P/C £700*\r\n▪ CHIMNEY STEELS – SHOULD THE CLIENT WISH TO REMOVE THE CHIMNEY THEN THE COST TO CONCEAL THE CHIMNEY STEELS WILL BE AN ADDITIONAL £1,000.\r\n▪ EXISTING PIPEWORK – THERE WILL BE AN ADDITIONAL COST FOR CUTTING HOLES THROUGH ANY STEEL BEAMS IN ORDER TO ACCOMMODATE ANY EXISTING PIPEWORK. p/c £100 per hole.','\r',char(13)),'\n',char(10)),NULL,'auto_child',NULL,NULL,0,893,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
