INSERT INTO line_items VALUES(4138,'foefep1a','optional_extras_page','Finishing Works Optional Extras','Flush External Patio - Notes','N',0.0,0.0,'admin_only',NULL,replace('●        The additional cost to dig up and create a flush external concrete patio floor with gentle gradient away from the house.\n●        Extend cross ventilation where necessary.\n●        Lay new tiles to the patio. \n●        Install a new French drain/ ACO chamber set within the floor along the rear kitchen wall.','\n',char(10)),NULL,NULL,'auto_child',NULL,NULL,0,997,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(4139,'foefep1b','optional_extras_page','Finishing Works Optional Extras','Flush External Patio - Guidance','N',0.0,0.0,'admin_only',NULL,NULL,replace('*PLEASE NOTE – THE CLIENT TO SUPPLY THE TILES.\n*PLEASE NOTE – THIS QUOTATION IS BASED ON REMOVING A STANDARD CONCRETE BASE OR PATIO WHICH IS LOWER THAN THE INTERNAL FLOOR LEVEL. \n*PLEASE NOTE – THIS QUOTATION IS BASED ON THE EXPECTATION THAT THE GROUND AREA IS LEVEL AND DOES NOT TAKE INTO ACCOUNT ANY VARYING LEVELS SPECIFIC TO YOUR PROPERTY. THE PRICE DOES NOT ALLOW FOR ANY RETAINING WALLS THAT MAY BE REQUIRED. THIS IS SUBJECT TO AN ON SITE INSPECTION. \n*PLEASE NOTE – IF IN ORDER TO CREATE A FLUSH PATIO, THE EXTERNAL GROUND LEVEL NEEDS TO BE RAISED BY MORE THAN 300mm THEN AN ADDITIONAL PLANNING APPLICATION WOULD BE RQUIRED – ADDITIONAL COST APPROX £600.','\n',char(10)),NULL,'auto_child',NULL,NULL,0,998,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
