INSERT INTO line_items VALUES(4158,'an3*','optional_extras_page','Additional Notes','Internal to external levels (steps)','Y',0.0,0.0,'admin_only',NULL,'Main house is level, 3 steps down to outrigger',NULL,NULL,'guidance',NULL,NULL,1,1017,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(4159,'an4*','optional_extras_page','Additional Notes','Internal heights','Y',0.0,0.0,'admin_only',NULL,'Above 2.35m',NULL,NULL,'guidance',NULL,NULL,1,1018,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
