INSERT INTO line_items VALUES(4161,'an6*','optional_extras_page','Additional Notes','Flush External walls','Y',0.0,0.0,'admin_only',NULL,'No - chimney',NULL,NULL,'guidance',NULL,NULL,1,1020,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(4162,'an7@','optional_extras_page','Additional Notes','Further Notes','Y',0.0,0.0,'admin_only',NULL,'None',NULL,NULL,'special',NULL,NULL,1,1021,'2026-08-19 17:18:11','2026-08-19 17:18:11',0,NULL,NULL,0,'General');
INSERT INTO line_items VALUES(4163,'sn1#','special_notes_page','Special Notes','Client Site Preparation','Y','','','admin_only','Client Site Preparation','It is the client’s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress.','',NULL,'parent',NULL,NULL,1,3,'2026-08-19 17:20:52','2026-08-19 17:42:01',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4165,'sn2#','special_notes_page','Special Notes','New Patio, Decking or Steps','Y','','','admin_only','New Patio, Decking or Steps','The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing’s team or foreman as directed by your project co-ordinator.','',NULL,'parent',NULL,NULL,1,5,'2026-08-19 17:20:52','2026-08-19 17:42:32',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4167,'sn3#','special_notes_page','Special Notes','Existing Decking & Fences','Y','','','admin_only','Existing Decking & Fences','Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works.','',NULL,'parent',NULL,NULL,1,6,'2026-08-19 17:20:52','2026-08-19 17:42:49',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4169,'sn4#','special_notes_page','Special Notes','Garden','Y','','','admin_only','Garden','Please be aware that the we will need to use your front & rear garden as a working area for the purposes of constructing the extension and storing the materials during the works. This will cause damage to garden, particularly the grass, and we would ask that any plants you which to retain are removed and safely stored prior to works commencing. It is advisable to allow a budget for re-turfing once the works are complete. ','*PLEASE NOTE – THAT IF YOU HAVE SYNTHETIC GRASS WE RECOMMEND THAT IT IS UPLIFTED AND REMOVED PRIOR TO WORKS COMMENCING AS WE CANNOT GUARANTEE IT WILL NOT GET DAMAGED.',NULL,'parent',NULL,NULL,1,9,'2026-08-19 17:20:52','2026-08-19 17:44:00',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4172,'sn5#','special_notes_page','Special Notes','House Alarms','Y','','','admin_only','House Alarms','It is the client’s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system.','',NULL,'parent',NULL,NULL,1,12,'2026-08-19 17:20:52','2026-08-19 17:44:24',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4174,'sn6#','special_notes_page','Special Notes','Access Areas & Front Door Re-decorating','Y','','','admin_only','Access Areas & Front Door Re-decorating','The client will need to budget for redecorating the ground floor hallway, front door and any other area used for access once the building works have been completed. This can be priced for by the finishing team. The company recommends the client take up floor coverings where possible. We will endeavour to protect any non-removable floor coverings but we are not liable for any damage.','*PLEASE NOTE – IF YOU HAVE AN OLD LOCKING SYSTEM TO THE FRONT DOOR, THERE IS A POSSIBILITY THAT THIS WILL NEED TO BE REPLACED AT THE END OF THE PROJECT.',NULL,'parent',NULL,NULL,1,14,'2026-08-19 17:20:52','2026-08-19 17:44:59',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4177,'sn7#','special_notes_page','Special Notes','Original Cornicing','Y','','','admin_only','Original Cornicing','Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing’s team or others.','',NULL,'parent',NULL,NULL,1,17,'2026-08-19 17:20:52','2026-08-19 17:45:23',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4179,'sn8#','special_notes_page','Special Notes','Cracking','Y','','','admin_only','Cracking','It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team.','',NULL,'parent',NULL,NULL,1,19,'2026-08-19 17:20:52','2026-08-19 17:45:52',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4181,'sn9#','special_notes_page','Special Notes','Trees, Hedges & Flowers','Y','','','admin_only','Trees, Hedges & Flowers','It’s the client’s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition.','',NULL,'parent',NULL,NULL,1,21,'2026-08-19 17:20:52','2026-08-19 17:46:11',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4183,'sn10#','special_notes_page','Special Notes','Gas/Electric Metres','Y','','','admin_only','Gas/Electric Metres','If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them.','',NULL,'parent',NULL,NULL,1,23,'2026-08-19 17:20:52','2026-08-19 17:46:49',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4185,'sn11#','special_notes_page','Special Notes','Facilities','Y','','','admin_only','Facilities','This quotation is based on the understanding that a WC will be made available for the Plus Rooms team throughout the project. If this is not possible then it will be the client’s responsibility to provide a port-a-loo.','',NULL,'parent',NULL,NULL,1,25,'2026-08-19 17:20:52','2026-08-19 17:47:11',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4187,'sn12#','special_notes_page','Special Notes','Client to Vacate','N','','','admin_only','Client to Vacate','The quotation is based on the understanding that the property will be vacant for the duration of the building works.','',NULL,'parent',NULL,NULL,1,27,'2026-08-19 17:20:52','2026-08-19 17:47:44',0,NULL,'[]',0,'General');
INSERT INTO line_items VALUES(4189,'new_1787172966','summary_page','Size of Extension','Size of extension','N','','','admin_only','The approximate extension size is','{one} full depth ({two} metres rear depth from the original rear wall) and by {three} metres full width with {four} metres width in the side return.','',NULL,'parent',NULL,NULL,1,0,'2026-08-19 20:56:06','2026-08-19 21:01:25',1,'Single Entry','[{"type":"Single Entry","helper_text":"depth","cost":false,"suffix":true,"suffix_value":"m"},{"type":"Single Entry","helper_text":"depth from original rear wall","cost":false,"suffix":true,"suffix_value":"m"},{"type":"Single Entry","helper_text":"full width","cost":false,"suffix":true,"suffix_value":"m"},{"type":"Single Entry","helper_text":"side return width","cost":false,"suffix":true,"suffix_value":"m"}]',0,'General');
