INSERT INTO quote_editor_layouts VALUES(4,703,'TEST QUOTE','[{"id": "form__special_notes_page__category__Special Notes", "type": "category_title", "snapshot": {"title": "Special Notes"}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 20, "margin_bottom": 5, "margin_top": 5, "padding": 12}}, {"id": "form__special_notes_page__special_notes_page__line_items__sn1#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Client Site Preparation", "line_code": "sn1#", "value": "It is the client\u2019s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 0}, {"id": "form__special_notes_page__special_notes_page__line_items__sn2#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "New Patio, Decking or Steps", "line_code": "sn2#", "value": "The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing\u2019s team or foreman as directed by your project co-ordinator."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 1}, {"id": "form__special_notes_page__special_notes_page__line_items__sn3#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Existing Decking & Fences", "line_code": "sn3#", "value": "Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 2}, {"id": "form__special_notes_page__special_notes_page__line_items__sn4#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Garden", "line_code": "sn4#", "value": "*PLEASE NOTE \u2013 THAT IF YOU HAVE SYNTHETIC GRASS WE RECOMMEND THAT IT IS UPLIFTED AND REMOVED PRIOR TO WORKS COMMENCING AS WE CANNOT GUARANTEE IT WILL NOT GET DAMAGED."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 3}, {"id": "form__special_notes_page__special_notes_page__line_items__sn5#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "House Alarms", "line_code": "sn5#", "value": "It is the client\u2019s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 4}, {"id": "form__special_notes_page__special_notes_page__line_items__sn6#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Access Areas & Front Door Re-decorating", "line_code": "sn6#", "value": "*PLEASE NOTE \u2013 IF YOU HAVE AN OLD LOCKING SYSTEM TO THE FRONT DOOR, THERE IS A POSSIBILITY THAT THIS WILL NEED TO BE REPLACED AT THE END OF THE PROJECT."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 5}, {"id": "form__special_notes_page__special_notes_page__line_items__sn7#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Original Cornicing", "line_code": "sn7#", "value": "Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing\u2019s team or others."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 6}, {"id": "form__special_notes_page__special_notes_page__line_items__sn8#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Cracking", "line_code": "sn8#", "value": "It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 7}, {"id": "form__special_notes_page__special_notes_page__line_items__sn9#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Trees, Hedges & Flowers", "line_code": "sn9#", "value": "It\u2019s the client\u2019s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 8}, {"id": "form__special_notes_page__special_notes_page__line_items__sn10#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Gas/Electric Metres", "line_code": "sn10#", "value": "If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 9}, {"id": "form__special_notes_page__special_notes_page__line_items__sn11#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Facilities", "line_code": "sn11#", "value": "This quotation is based on the understanding that a WC will be made available for the Plus Rooms team throughout the project. If this is not possible then it will be the client\u2019s responsibility to provide a port-a-loo."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 10}]','{"document_styles": {"font_family": "Arial, sans-serif", "font_size_base": 16, "header_html": "", "footer_html": "", "header_font_size": 10, "footer_font_size": 8, "page_size": "A4", "header_hide_on_cover": false, "footer_hide_on_cover": false, "margins": {"margin_top": 20, "margin_bottom": 20, "margin_left": 25, "margin_right": 25}, "typography": {"h1": {"family": "", "weight": "", "size": 24, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "h2": {"family": "Arial, sans-serif", "weight": "500", "size": 20, "bold": false, "italic": false, "underline": false, "color": "#8a0000"}, "h3": {"family": "", "weight": "", "size": 18, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "para": {"family": "Arial, sans-serif", "weight": "300", "size": 14, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "notes": {"family": "", "weight": "", "size": 14, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "guide": {"family": "", "weight": "", "size": 14, "bold": false, "italic": false, "underline": false, "color": "#000000"}}, "tables": {"border": "1px solid #ccc", "header_bg": "#f5f5f5", "row_bg": "#ffffff", "alt_row_bg": "#fafafa", "font_size": 14}, "images": {"frame": "none", "shadow": false}, "links": {"color": "#0d6efd", "underline": true}}}',0,'2026-08-12 12:10:42','2026-08-12 12:10:42');
INSERT INTO quote_editor_layouts VALUES(5,703,'TEST ACCOUNT','[{"id": "form__special_notes_page__category__Special Notes", "type": "category_title", "snapshot": {"title": "Special Notes"}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 20, "margin_bottom": 5, "margin_top": 5, "padding": 12}}, {"id": "form__special_notes_page__special_notes_page__line_items__sn1#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Client Site Preparation", "line_code": "sn1#", "output_guidance": "", "output_notes": "It is the client\u2019s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress.", "value": "It is the client\u2019s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress."}, "editor_overrides": {"content": "\n        <strong>Client Site Preparation:</strong> It is the client\u2019s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 0}, {"id": "form__special_notes_page__special_notes_page__line_items__sn2#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "New Patio, Decking or Steps", "line_code": "sn2#", "output_guidance": "", "output_notes": "The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing\u2019s team or foreman as directed by your project co-ordinator.", "value": "The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing\u2019s team or foreman as directed by your project co-ordinator."}, "editor_overrides": {"content": "\n        <strong>New Patio, Decking or Steps:</strong> The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing\u2019s team or foreman as directed by your project co-ordinator.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 1}, {"id": "form__special_notes_page__special_notes_page__line_items__sn3#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Existing Decking & Fences", "line_code": "sn3#", "output_guidance": "", "output_notes": "Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works.", "value": "Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works."}, "editor_overrides": {"content": "\n        <strong>Existing Decking &amp; Fences:</strong> Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 2}, {"id": "form__special_notes_page__special_notes_page__line_items__sn4#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Garden", "line_code": "sn4#", "output_guidance": "*PLEASE NOTE \u2013 THAT IF YOU HAVE SYNTHETIC GRASS WE RECOMMEND THAT IT IS UPLIFTED AND REMOVED PRIOR TO WORKS COMMENCING AS WE CANNOT GUARANTEE IT WILL NOT GET DAMAGED.", "output_notes": "Please be aware that the we will need to use your front & rear garden as a working area for the purposes of constructing the extension and storing the materials during the works. This will cause damage to garden, particularly the grass, and we would ask that any plants you which to retain are removed and safely stored prior to works commencing. It is advisable to allow a budget for re-turfing once the works are complete.", "value": "Please be aware that the we will need to use your front & rear garden as a working area for the purposes of constructing the extension and storing the materials during the works. This will cause damage to garden, particularly the grass, and we would ask that any plants you which to retain are removed and safely stored prior to works commencing. It is advisable to allow a budget for re-turfing once the works are complete."}, "editor_overrides": {"content": "\n        <strong>Garden:</strong> Please be aware that the we will need to use your front &amp; rear garden as a working area for the purposes of constructing the extension and storing the materials during the works. This will cause damage to garden, particularly the grass, and we would ask that any plants you which to retain are removed and safely stored prior to works commencing. It is advisable to allow a budget for re-turfing once the works are complete.<br><span style=\"color: rgb(0, 129, 184); font-family: Arial, sans-serif; font-size: 8px; font-style: italic;\"><br>*PLEASE NOTE \u2013 THAT IF YOU HAVE SYNTHETIC GRASS WE RECOMMEND THAT IT IS UPLIFTED AND REMOVED PRIOR TO WORKS COMMENCING AS WE CANNOT GUARANTEE IT WILL NOT GET DAMAGED.<br><br></span><div><span style=\"color: rgb(0, 129, 184); font-family: Arial, sans-serif; font-size: 8px; font-style: italic;\"><br></span></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 3}, {"id": "form__special_notes_page__special_notes_page__line_items__sn5#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "House Alarms", "line_code": "sn5#", "output_guidance": "", "output_notes": "It is the client\u2019s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system.", "value": "It is the client\u2019s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system."}, "editor_overrides": {"content": "\n        <strong>House Alarms:</strong> It is the client\u2019s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 4}, {"id": "form__special_notes_page__special_notes_page__line_items__sn6#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Access Areas & Front Door Re-decorating", "line_code": "sn6#", "output_guidance": "*PLEASE NOTE \u2013 IF YOU HAVE AN OLD LOCKING SYSTEM TO THE FRONT DOOR, THERE IS A POSSIBILITY THAT THIS WILL NEED TO BE REPLACED AT THE END OF THE PROJECT.", "output_notes": "The client will need to budget for redecorating the ground floor hallway, front door and any other area used for access once the building works have been completed. This can be priced for by the finishing team. The company recommends the client take up floor coverings where possible. We will endeavour to protect any non-removable floor coverings but we are not liable for any damage.", "value": "The client will need to budget for redecorating the ground floor hallway, front door and any other area used for access once the building works have been completed. This can be priced for by the finishing team. The company recommends the client take up floor coverings where possible. We will endeavour to protect any non-removable floor coverings but we are not liable for any damage."}, "editor_overrides": {"content": "\n        <strong>Access Areas &amp; Front Door Re-decorating:</strong> The client will need to budget for redecorating the ground floor hallway, front door and any other area used for access once the building works have been completed. This can be priced for by the finishing team. The company recommends the client take up floor coverings where possible. We will endeavour to protect any non-removable floor coverings but we are not liable for any damage.<br><span style=\"color: rgb(0, 129, 184); font-family: Arial, sans-serif; font-size: 8px; font-style: italic;\"><br>*PLEASE NOTE \u2013 IF YOU HAVE AN OLD LOCKING SYSTEM TO THE FRONT DOOR, THERE IS A POSSIBILITY THAT THIS WILL NEED TO BE REPLACED AT THE END OF THE PROJECT.<br><br></span><div><span style=\"color: rgb(0, 129, 184); font-family: Arial, sans-serif; font-size: 8px; font-style: italic;\"><br></span></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 5}, {"id": "form__special_notes_page__special_notes_page__line_items__sn7#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Original Cornicing", "line_code": "sn7#", "output_guidance": "", "output_notes": "Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing\u2019s team or others.", "value": "Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing\u2019s team or others."}, "editor_overrides": {"content": "\n        <strong>Original Cornicing:</strong> Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing\u2019s team or others.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 6}, {"id": "form__special_notes_page__special_notes_page__line_items__sn8#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Cracking", "line_code": "sn8#", "output_guidance": "", "output_notes": "It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team.", "value": "It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team."}, "editor_overrides": {"content": "\n        <strong>Cracking:</strong> It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 7}, {"id": "form__special_notes_page__special_notes_page__line_items__sn9#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Trees, Hedges & Flowers", "line_code": "sn9#", "output_guidance": "", "output_notes": "It\u2019s the client\u2019s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition.", "value": "It\u2019s the client\u2019s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition."}, "editor_overrides": {"content": "\n        <strong>Trees, Hedges &amp; Flowers:</strong> It\u2019s the client\u2019s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 8}, {"id": "form__special_notes_page__special_notes_page__line_items__sn10#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Gas/Electric Metres", "line_code": "sn10#", "output_guidance": "", "output_notes": "If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them.", "value": "If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them."}, "editor_overrides": {"content": "\n        <strong>Gas/Electric Metres:</strong> If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 9}, {"id": "form__special_notes_page__special_notes_page__line_items__sn11#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Facilities", "line_code": "sn11#", "output_guidance": "", "output_notes": "This quotation is based on the understanding that a WC will be made available for the Plus Rooms team throughout the project. If this is not possible then it will be the client\u2019s responsibility to provide a port-a-loo.", "value": "This quotation is based on the understanding that a WC will be made available for the Plus Rooms team throughout the project. If this is not possible then it will be the client\u2019s responsibility to provide a port-a-loo."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 10}]','{"document_styles": {"font_family": "Arial, sans-serif", "font_size_base": 16, "header_html": "", "footer_html": "", "header_font_size": 10, "footer_font_size": 8, "page_size": "A4", "header_hide_on_cover": false, "footer_hide_on_cover": false, "margins": {"margin_top": 20, "margin_bottom": 20, "margin_left": 25, "margin_right": 25}, "typography": {"h1": {"family": "", "weight": "", "size": 24, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "h2": {"family": "Arial, sans-serif", "weight": "500", "size": 20, "bold": false, "italic": false, "underline": false, "color": "#8a0000"}, "h3": {"family": "", "weight": "", "size": 18, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "para": {"family": "Arial, sans-serif", "weight": "300", "size": 12, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "notes": {"family": "", "weight": "", "size": 14, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "guide": {"family": "Arial, sans-serif", "weight": "300", "size": 8, "bold": false, "italic": false, "underline": false, "color": "#069b9d"}, "guidance": {"family": "Arial, sans-serif", "weight": "300", "size": 8, "bold": false, "italic": true, "underline": false, "color": "#0081b8"}}, "tables": {"border": "1px solid #ccc", "header_bg": "#f5f5f5", "row_bg": "#ffffff", "alt_row_bg": "#fafafa", "font_size": 14}, "images": {"frame": "none", "shadow": false}, "links": {"color": "#0d6efd", "underline": true}}}',0,'2026-08-12 15:29:33','2026-08-12 15:29:33');
INSERT INTO quote_editor_layouts VALUES(6,703,'TEST QUOTE','[{"id": "form__special_notes_page__category__Special Notes", "type": "category_title", "snapshot": {"title": "Special Notes"}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 20, "margin_bottom": 5, "margin_top": 5, "padding": 12}}, {"id": "form__special_notes_page__special_notes_page__line_items__sn1#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Client Site Preparation", "line_code": "sn1#", "output_guidance": "", "output_notes": "It is the client\u2019s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress.", "value": "It is the client\u2019s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress."}, "editor_overrides": {"content": "\n        <strong>Client Site Preparation:</strong> It is the client\u2019s responsibility to arrange for the uplift and/or removal of carpet and personal items prior to works commencing. Should this not be done then the building team will sheet over the existing carpet. Any furniture that is to remain, is to be protected by the client. Plus Rooms do not guarantee against damage or dust ingress.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 0}, {"id": "form__special_notes_page__special_notes_page__line_items__sn2#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "New Patio, Decking or Steps", "line_code": "sn2#", "output_guidance": "", "output_notes": "The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing\u2019s team or foreman as directed by your project co-ordinator.", "value": "The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing\u2019s team or foreman as directed by your project co-ordinator."}, "editor_overrides": {"content": "\n        <strong>New Patio, Decking or Steps:</strong> The quotation has not made any allowance for an external decking, patio or steps leading out to the garden. This can be priced on site direct by either the finishing\u2019s team or foreman as directed by your project co-ordinator.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 1}, {"id": "form__special_notes_page__special_notes_page__line_items__sn3#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Existing Decking & Fences", "line_code": "sn3#", "output_guidance": "", "output_notes": "Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works.", "value": "Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works."}, "editor_overrides": {"content": "\n        <strong>Existing Decking &amp; Fences:</strong> Any existing decking and fences will be removed and disposed of as part of the works. If you would like to retain any decking or fences, please arrange for these to be removed and safely stored prior to the commencement of the works.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 2}, {"id": "form__special_notes_page__special_notes_page__line_items__sn4#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Garden", "line_code": "sn4#", "output_guidance": "*PLEASE NOTE \u2013 THAT IF YOU HAVE SYNTHETIC GRASS WE RECOMMEND THAT IT IS UPLIFTED AND REMOVED PRIOR TO WORKS COMMENCING AS WE CANNOT GUARANTEE IT WILL NOT GET DAMAGED.", "output_notes": "Please be aware that the we will need to use your front & rear garden as a working area for the purposes of constructing the extension and storing the materials during the works. This will cause damage to garden, particularly the grass, and we would ask that any plants you which to retain are removed and safely stored prior to works commencing. It is advisable to allow a budget for re-turfing once the works are complete.", "value": "Please be aware that the we will need to use your front & rear garden as a working area for the purposes of constructing the extension and storing the materials during the works. This will cause damage to garden, particularly the grass, and we would ask that any plants you which to retain are removed and safely stored prior to works commencing. It is advisable to allow a budget for re-turfing once the works are complete."}, "editor_overrides": {"content": "\n        <strong>Garden:</strong> Please be aware that the we will need to use your front &amp; rear garden as a working area for the purposes of constructing the extension and storing the materials during the works. This will cause damage to garden, particularly the grass, and we would ask that any plants you which to retain are removed and safely stored prior to works commencing. It is advisable to allow a budget for re-turfing once the works are complete.<div class=\"preview-guidance\" style=\"font-family:Arial, sans-serif;font-size:8px;color:#0081b8;font-weight:300;font-style:italic\">*PLEASE NOTE \u2013 THAT IF YOU HAVE SYNTHETIC GRASS WE RECOMMEND THAT IT IS UPLIFTED AND REMOVED PRIOR TO WORKS COMMENCING AS WE CANNOT GUARANTEE IT WILL NOT GET DAMAGED.<br><br></div>\n      "}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 3}, {"id": "form__special_notes_page__special_notes_page__line_items__sn5#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "House Alarms", "line_code": "sn5#", "output_guidance": "", "output_notes": "It is the client\u2019s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system.", "value": "It is the client\u2019s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system."}, "editor_overrides": {"content": "\n        <strong>House Alarms:</strong> It is the client\u2019s responsibility to disconnect or relocate the alarm sensors prior to works taking place. Plus Rooms do not take any responsibility/ liability for damage caused to the existing system.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 4}, {"id": "form__special_notes_page__special_notes_page__line_items__sn6#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Access Areas & Front Door Re-decorating", "line_code": "sn6#", "output_guidance": "*PLEASE NOTE \u2013 IF YOU HAVE AN OLD LOCKING SYSTEM TO THE FRONT DOOR, THERE IS A POSSIBILITY THAT THIS WILL NEED TO BE REPLACED AT THE END OF THE PROJECT.", "output_notes": "The client will need to budget for redecorating the ground floor hallway, front door and any other area used for access once the building works have been completed. This can be priced for by the finishing team. The company recommends the client take up floor coverings where possible. We will endeavour to protect any non-removable floor coverings but we are not liable for any damage.", "value": "The client will need to budget for redecorating the ground floor hallway, front door and any other area used for access once the building works have been completed. This can be priced for by the finishing team. The company recommends the client take up floor coverings where possible. We will endeavour to protect any non-removable floor coverings but we are not liable for any damage."}, "editor_overrides": {"content": "\n        <strong>Access Areas &amp; Front Door Re-decorating:</strong> The client will need to budget for redecorating the ground floor hallway, front door and any other area used for access once the building works have been completed. This can be priced for by the finishing team. The company recommends the client take up floor coverings where possible. We will endeavour to protect any non-removable floor coverings but we are not liable for any damage.<div class=\"preview-guidance\" style=\"font-family:Arial, sans-serif;font-size:8px;color:#0081b8;font-weight:300;font-style:italic\">*PLEASE NOTE \u2013 IF YOU HAVE AN OLD LOCKING SYSTEM TO THE FRONT DOOR, THERE IS A POSSIBILITY THAT THIS WILL NEED TO BE REPLACED AT THE END OF THE PROJECT.<br><br></div>\n      "}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 5}, {"id": "form__special_notes_page__special_notes_page__line_items__sn7#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Original Cornicing", "line_code": "sn7#", "output_guidance": "", "output_notes": "Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing\u2019s team or others.", "value": "Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing\u2019s team or others."}, "editor_overrides": {"content": "\n        <strong>Original Cornicing:</strong> Plus Rooms are not responsible for any damage to existing architrave skirting boards, coving, dado and picture rails or similar. The cost to repair/ replace such items is to be priced directly by the finishing\u2019s team or others.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 6}, {"id": "form__special_notes_page__special_notes_page__line_items__sn8#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Cracking", "line_code": "sn8#", "output_guidance": "", "output_notes": "It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team.", "value": "It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team."}, "editor_overrides": {"content": "\n        <strong>Cracking:</strong> It is reasonable to assume that cracks will occur when supporting walls are removed and steel beams are inserted. Plus Rooms are responsible for all structural cracking. Cosmetic cracks and hairline cracks that require filling and painting fall under decoration works and can be priced for by the finishings team.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 7}, {"id": "form__special_notes_page__special_notes_page__line_items__sn9#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Trees, Hedges & Flowers", "line_code": "sn9#", "output_guidance": "", "output_notes": "It\u2019s the client\u2019s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition.", "value": "It\u2019s the client\u2019s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition."}, "editor_overrides": {"content": "\n        <strong>Trees, Hedges &amp; Flowers:</strong> It\u2019s the client\u2019s responsibility to arrange for any trees and hedges to be removed prior to the building works starting should they be inside or within close proximity to where the building works are to take place. Any flowers or plants not removed will be skipped as part of the demolition.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 8}, {"id": "form__special_notes_page__special_notes_page__line_items__sn10#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Gas/Electric Metres", "line_code": "sn10#", "output_guidance": "", "output_notes": "If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them.", "value": "If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them."}, "editor_overrides": {"content": "\n        <strong>Gas/Electric Metres:</strong> If the gas or/ and the electric metre is positioned in a location where the building works are taking place then it is the clients responsibility to arrange for their suppliers to relocate them.\n      <div><br></div>"}, "flags": {"editor_dirty": true, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 9}, {"id": "form__special_notes_page__special_notes_page__line_items__sn11#", "type": "form_question", "snapshot": {"category": "Special Notes", "label": "Facilities", "line_code": "sn11#", "output_guidance": "", "output_notes": "This quotation is based on the understanding that a WC will be made available for the Plus Rooms team throughout the project. If this is not possible then it will be the client\u2019s responsibility to provide a port-a-loo.", "value": "This quotation is based on the understanding that a WC will be made available for the Plus Rooms team throughout the project. If this is not possible then it will be the client\u2019s responsibility to provide a port-a-loo."}, "editor_overrides": {}, "flags": {"editor_dirty": false, "source_dirty": false}, "settings": {"alignment": "left", "font_size": 16, "margin_bottom": 2, "margin_top": 2, "padding": 12}, "list_group_id": "list_1", "list_type": "ol", "list_index": 10}]','{"document_styles": {"font_family": "Arial, sans-serif", "font_size_base": 16, "header_html": "", "footer_html": "", "header_font_size": 10, "footer_font_size": 8, "page_size": "A4", "header_hide_on_cover": false, "footer_hide_on_cover": false, "margins": {"margin_top": 20, "margin_bottom": 20, "margin_left": 25, "margin_right": 25}, "typography": {"h1": {"family": "", "weight": "", "size": 24, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "h2": {"family": "Arial, sans-serif", "weight": "500", "size": 20, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "h3": {"family": "", "weight": "", "size": 18, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "para": {"family": "Arial, sans-serif", "weight": "300", "size": 16, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "notes": {"family": "", "weight": "", "size": 14, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "guide": {"family": "Arial, sans-serif", "weight": "300", "size": 14, "bold": false, "italic": false, "underline": false, "color": "#000000"}, "guidance": {"family": "Arial, sans-serif", "weight": "300", "size": 14, "bold": false, "italic": false, "underline": false, "color": "#000000"}}, "tables": {"border": "1px solid #ccc", "header_bg": "#f5f5f5", "row_bg": "#ffffff", "alt_row_bg": "#fafafa", "font_size": 14}, "images": {"frame": "none", "shadow": false}, "links": {"color": "#0d6efd", "underline": true}}}',0,'2026-08-12 17:15:47','2026-08-12 17:15:47');
