PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE tenants (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            slug TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE form_templates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            tenant_id INTEGER NOT NULL,
            key TEXT NOT NULL,
            name TEXT NOT NULL,
            description TEXT,
            status TEXT NOT NULL DEFAULT 'active',
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, settings_json TEXT DEFAULT '{}',
            UNIQUE (tenant_id, key),
            FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
        );
CREATE TABLE form_template_versions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            form_template_id INTEGER NOT NULL,
            version INTEGER NOT NULL,
            source TEXT NOT NULL DEFAULT 'page_schemas_json',
            is_published INTEGER NOT NULL DEFAULT 1,
            payload_json TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (form_template_id, version),
            FOREIGN KEY (form_template_id) REFERENCES form_templates(id) ON DELETE CASCADE
        );
CREATE TABLE question_templates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            page_template_id INTEGER NOT NULL,
            question_key TEXT NOT NULL,
            question_type TEXT NOT NULL,
            label TEXT,
            storage_key TEXT,
            display_order INTEGER NOT NULL,
            metadata_json TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP, allow_user_override INTEGER NOT NULL DEFAULT 0,
            UNIQUE (page_template_id, question_key),
            FOREIGN KEY (page_template_id) REFERENCES page_templates(id) ON DELETE CASCADE
        );
CREATE TABLE logic_rules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            code TEXT NOT NULL UNIQUE,
            description TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE template_rule_bindings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            form_template_version_id INTEGER NOT NULL,
            rule_id INTEGER NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (form_template_version_id, rule_id),
            FOREIGN KEY (form_template_version_id) REFERENCES form_template_versions(id) ON DELETE CASCADE,
            FOREIGN KEY (rule_id) REFERENCES logic_rules(id) ON DELETE CASCADE
        );
CREATE TABLE option_sets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            form_template_version_id INTEGER NOT NULL,
            prefix TEXT NOT NULL,
            label TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (form_template_version_id, prefix),
            FOREIGN KEY (form_template_version_id) REFERENCES form_template_versions(id) ON DELETE CASCADE
        );
CREATE TABLE option_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            option_set_id INTEGER NOT NULL,
            line_code TEXT NOT NULL,
            label TEXT NOT NULL,
            is_included INTEGER NOT NULL DEFAULT 0,
            sort_order INTEGER NOT NULL DEFAULT 0,
            metadata_json TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (option_set_id, line_code),
            FOREIGN KEY (option_set_id) REFERENCES option_sets(id) ON DELETE CASCADE
        );
CREATE TABLE line_items (
            id                   INTEGER PRIMARY KEY AUTOINCREMENT,
            line_code            TEXT NOT NULL UNIQUE,
            form_page            TEXT,
            category             TEXT NOT NULL,
            internal_description TEXT,
            include_default      TEXT NOT NULL DEFAULT 'N',
            unit_cost            REAL DEFAULT 0.0,
            units                REAL DEFAULT 0.0,
            pricing_visibility   TEXT NOT NULL DEFAULT 'admin_only',
            output_title         TEXT,
            output_notes         TEXT,
            output_guidance      TEXT,
            parent_code          TEXT,
            item_role            TEXT NOT NULL DEFAULT 'standalone',
            input_type           TEXT,
            trigger_parent_code  TEXT,
            form_visible         INTEGER NOT NULL DEFAULT 1,
            sort_order           INTEGER NOT NULL DEFAULT 0,
            created_at           DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at           DATETIME DEFAULT CURRENT_TIMESTAMP
        , is_follow_up INTEGER NOT NULL DEFAULT 0, follow_up_type TEXT, follow_up_config TEXT, allow_user_override INTEGER DEFAULT 0, output_group TEXT DEFAULT 'General');
CREATE TABLE category_templates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            form_template_version_id INTEGER NOT NULL,
            page_template_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            display_order INTEGER NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP, description TEXT DEFAULT '', output_group TEXT DEFAULT "General", image_url TEXT DEFAULT '',
            UNIQUE (page_template_id, name),
            FOREIGN KEY (form_template_version_id) REFERENCES form_template_versions(id) ON DELETE CASCADE,
            FOREIGN KEY (page_template_id) REFERENCES page_templates(id) ON DELETE CASCADE
        );
CREATE TABLE IF NOT EXISTS "page_templates" (id INTEGER PRIMARY KEY AUTOINCREMENT, form_template_version_id INTEGER NOT NULL, page_key TEXT NOT NULL, title TEXT NOT NULL, previous_endpoint TEXT, next_endpoint TEXT, display_order INTEGER NOT NULL, metadata_json TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, description TEXT DEFAULT '', UNIQUE (form_template_version_id, page_key), FOREIGN KEY (form_template_version_id) REFERENCES form_template_versions(id) ON DELETE CASCADE);
CREATE TABLE quotes (
        id                   INTEGER PRIMARY KEY AUTOINCREMENT,
        template_key         TEXT NOT NULL,
        client_name          TEXT,
        client_address       TEXT,
        project_date         TEXT,
        status               TEXT NOT NULL DEFAULT 'draft',
        deposit_pct          REAL NOT NULL DEFAULT 0.10,
        completion_pct       REAL NOT NULL DEFAULT 0.10,
        subtotal             REAL DEFAULT 0.0,
        adjustment_total     REAL DEFAULT 0.0,
        grand_total          REAL DEFAULT 0.0,
        deposit_amount       REAL DEFAULT 0.0,
        completion_amount    REAL DEFAULT 0.0,
        notes                TEXT,
        created_at           DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at           DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE quote_line_items (
        id                   INTEGER PRIMARY KEY AUTOINCREMENT,
        quote_id             INTEGER NOT NULL,
        line_code            TEXT NOT NULL,
        output_group         TEXT NOT NULL DEFAULT 'General',
        category             TEXT,
        output_title         TEXT,
        internal_description TEXT,
        unit_cost            REAL DEFAULT 0.0,
        units                REAL DEFAULT 0.0,
        line_total           REAL DEFAULT 0.0,
        pricing_visibility   TEXT NOT NULL DEFAULT 'admin_only',
        sort_order           INTEGER NOT NULL DEFAULT 0,
        is_custom            INTEGER NOT NULL DEFAULT 0,
        metadata_json        TEXT,
        FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE CASCADE
    );
CREATE TABLE quote_adjustments (
        id                   INTEGER PRIMARY KEY AUTOINCREMENT,
        quote_id             INTEGER NOT NULL,
        adjustment_type      TEXT NOT NULL DEFAULT 'discount',
        label                TEXT NOT NULL,
        amount               REAL NOT NULL DEFAULT 0.0,
        is_percentage        INTEGER NOT NULL DEFAULT 0,
        target_group         TEXT,
        sort_order           INTEGER NOT NULL DEFAULT 0,
        FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE CASCADE
    );
CREATE TABLE output_templates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            form_template_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            sections_json TEXT NOT NULL DEFAULT '{}',
            css_json TEXT NOT NULL DEFAULT '{}',
            is_default INTEGER NOT NULL DEFAULT 0,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (form_template_id) REFERENCES form_templates(id) ON DELETE CASCADE
        );
CREATE TABLE quote_editor_layouts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            form_template_id INTEGER NOT NULL,
            name TEXT NOT NULL DEFAULT 'Default',
            blocks_json TEXT NOT NULL DEFAULT '[]',
            settings_json TEXT NOT NULL DEFAULT '{}',
            is_default INTEGER NOT NULL DEFAULT 0,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (form_template_id) REFERENCES form_templates(id) ON DELETE CASCADE
        );
CREATE TABLE saved_quotes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            form_template_id INTEGER NOT NULL,
            layout_id INTEGER,
            name TEXT NOT NULL,
            client_name TEXT,
            notes TEXT,
            blocks_json TEXT NOT NULL,
            settings_json TEXT NOT NULL DEFAULT '{}',
            status TEXT NOT NULL DEFAULT 'draft',
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, form_data TEXT DEFAULT '{}',
            FOREIGN KEY (form_template_id) REFERENCES form_templates(id) ON DELETE CASCADE
        );
CREATE TABLE saved_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            session_data TEXT NOT NULL,
            user_id INTEGER,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
DELETE FROM sqlite_sequence;
COMMIT;
